'use strict';
// Global navigation bar: distinct Reply Debt mark + company search + primary tabs + Me menu.
const { AFFILIATION_NOTICE, PRODUCT_NAME, REPO_URL } = __req("assets/js/config.js");
const { h, isMobileViewport } = __req("assets/js/ui/h.js");
const { icon, logo } = __req("assets/js/ui/icons.js");
